function createMirrorMaterial(color = 0xffffff) {
  return new THREE.MeshPhysicalMaterial({
    color: color,
    metalness: 1.0,
    roughness: 0.05,
    clearcoat: 1.0,
    clearcoatRoughness: 0.05,
    reflectivity: 1.0,
    envMapIntensity: 1.2
  });
}

function createParametricSculpture(type, splinePoints, speed, scale = 1, color = 0xffffff) {
  const group = new THREE.Group();
  let mesh;

  const material = createMirrorMaterial(color);

  switch(type) {
    case 'torusKnot':
      const tkGeo = new THREE.TorusKnotGeometry(0.8, 0.25, 128, 32, 2, 3);
      mesh = new THREE.Mesh(tkGeo, material);
      break;
    case 'twistedSphere':
      const sphereGeo = new THREE.IcosahedronGeometry(1.2, 4);
      const posAttribute = sphereGeo.attributes.position;
      const vertex = new THREE.Vector3();
      for (let i = 0; i < posAttribute.count; i++) {
        vertex.fromBufferAttribute(posAttribute, i);
        const noise = Math.sin(vertex.x * 3) * Math.cos(vertex.y * 3) * Math.sin(vertex.z * 3) * 0.2;
        vertex.addScalar(noise);
        posAttribute.setXYZ(i, vertex.x, vertex.y, vertex.z);
      }
      sphereGeo.computeVertexNormals();
      mesh = new THREE.Mesh(sphereGeo, material);
      break;
    case 'helix':
      const helixPoints = [];
      for (let i = 0; i <= 100; i++) {
        const t = (i / 100) * Math.PI * 6;
        helixPoints.push(new THREE.Vector3(
          Math.cos(t) * 0.8,
          (i - 50) * 0.04,
          Math.sin(t) * 0.8
        ));
      }
      const helixGeo = new THREE.TubeGeometry(
        new THREE.CatmullRomCurve3(helixPoints),
        64,
        0.15,
        16,
        false
      );
      mesh = new THREE.Mesh(helixGeo, material);
      break;
    case 'mobius':
      const mobiusPoints = [];
      for (let i = 0; i <= 200; i++) {
        const t = (i / 200) * Math.PI * 2;
        const x = Math.cos(t) * 1.2 + Math.cos(t * 2) * 0.6;
        const y = Math.sin(t * 3) * 0.4;
        const z = Math.sin(t) * 1.2 + Math.sin(t * 2) * 0.6;
        mobiusPoints.push(new THREE.Vector3(x, y, z));
      }
      const mobiusCurve = new THREE.CatmullRomCurve3(mobiusPoints, true);
      const mobiusGeo = new THREE.TubeGeometry(mobiusCurve, 100, 0.12, 12, true);
      mesh = new THREE.Mesh(mobiusGeo, material);
      break;
    case 'crystal':
      const crystalGeo = new THREE.OctahedronGeometry(1.1, 0);
      mesh = new THREE.Mesh(crystalGeo, material);
      break;
  }

  mesh.castShadow = true;
  mesh.receiveShadow = true;
  mesh.scale.setScalar(scale);
  group.add(mesh);

  const curve = new THREE.CatmullRomCurve3(splinePoints, true);
  scene.add(group);

  sculptures.push({
    group: group,
    mesh: mesh,
    curve: curve,
    speed: speed,
    offset: Math.random() * 100,
    rotSpeed: {
      x: (Math.random() - 0.5) * 0.5,
      y: (Math.random() - 0.5) * 0.5,
      z: (Math.random() - 0.5) * 0.5
    }
  });
}

