camera.position.set(8, 5, 12);
camera.lookAt(0, 0, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  sculptures.forEach((sculpt, i) => {
    const time = t * sculpt.speed + sculpt.offset;
    const point = sculpt.curve.getPointAt(time % 1);
    const tangent = sculpt.curve.getTangentAt(time % 1);

    sculpt.group.position.copy(point);
    sculpt.group.position.y += Math.sin(t * 0.5 + sculpt.offset) * 0.3;

    sculpt.mesh.rotation.x += sculpt.rotSpeed.x * 0.02;
    sculpt.mesh.rotation.y += sculpt.rotSpeed.y * 0.02;
    sculpt.mesh.rotation.z += sculpt.rotSpeed.z * 0.02;

    sculpt.group.lookAt(point.clone().add(tangent));
  });

  lightArray.forEach((light, i) => {
    const phase = t * 0.5 + (i * Math.PI * 0.67);
    light.intensity = 0.6 + Math.sin(phase) * 0.4;
    light.position.y = 3 + Math.sin(t * 0.3 + i) * 2;
  });

  keyLight.position.x = 8 + Math.sin(t * 0.2) * 2;
  keyLight.position.z = 6 + Math.cos(t * 0.2) * 2;

  particles.rotation.y = t * 0.02;
  particles.position.y = Math.sin(t * 0.1) * 0.5;

  camera.position.x = 8 + Math.sin(t * 0.08) * 3;
  camera.position.z = 12 + Math.cos(t * 0.08) * 3;
  camera.lookAt(0, 0, 0);

  renderer.render(scene, camera);
}

animate();
